ST.xhtml:p:
Rtring_1(CLK := g_bRecordRatoteAngleBeforeCenteringM);
Rtring_2(CLK := g_bRecordRatoteAngleBeforCuttingM);
IF Rtring_1.Q THEN
  g_bRecordRatoteAngleBeforeCenteringM := FALSE;
  dRecordAngle1 := g_diUMachineCoordinate;
END_IF;
IF Rtring_2.Q THEN
  g_bRecordRatoteAngleBeforCuttingM := FALSE;
  dRecordAngle2 := g_diUMachineCoordinate;
  g_dRatoteAngleDifference := dRecordAngle2 - dRecordAngle1;
END_IF;



(*计算X的工件坐标*)
g_fXWorkCoordinate := g_diXMachineCoordinate - g_dBeamCenterPos;

(*计算U的工件坐标*)
g_fUWorkCoordinate := g_diUMachineCoordinate - g_dAngle - g_dRatoteAngleDifference;

dWorkCoordU := FUN_FMOD(g_fUWorkCoordinate,FALSE);

(*IF (dWorkCoordU > -90.0 AND dWorkCoordU < 90.0)  THEN*)
IF (dWorkCoordU > -10.0 AND dWorkCoordU < 10.0)  OR  (dWorkCoordU > -370.0 AND dWorkCoordU < -350.0) OR  (dWorkCoordU > 350.0 AND dWorkCoordU < 370.0) THEN
  fLeft := -DIV(IN1 := g_dSquareLenght,IN2 := 2.0)+10.0 + g_fCornerRadius;
  fRight := DIV(IN1 := g_dSquareLenght,IN2 := 2.0) -10.0 - g_fCornerRadius;
  IF g_fXWorkCoordinate > fLeft AND g_fXWorkCoordinate < fRight THEN
    g_bLaserOnPlane := FALSE;
  ELSE 
    g_bLaserOnPlane := TRUE;
    IF g_fXWorkCoordinate <= 0.0  THEN
    g_fPlaneX_Site := g_fXWorkCoordinate - fLeft + 10.0;
    ELSIF g_fXWorkCoordinate > 0.0 THEN
      g_fPlaneX_Site := fRight - g_fXWorkCoordinate +10.0;
    END_IF; 
  END_IF;

(*ELSIF  (dWorkCoordU >=90.0 AND dWorkCoordU <180.0)  OR  (dWorkCoordU > -360.0 AND dWorkCoordU <= -270.0) THEN*)
ELSIF  (dWorkCoordU >80.0 AND dWorkCoordU <100.0)  OR  (dWorkCoordU > -280.0 AND dWorkCoordU < -260.0) THEN
  fLeft := -DIV(IN1 := g_dSquareWidth,IN2 := 2.0)+10.0 + g_fCornerRadius;
  fRight := DIV(IN1 := g_dSquareWidth,IN2 := 2.0) -10.0 - g_fCornerRadius;
  IF g_fXWorkCoordinate > fLeft AND g_fXWorkCoordinate < fRight THEN
    g_bLaserOnPlane := FALSE;
  ELSE 
    g_bLaserOnPlane := TRUE;
    IF g_fXWorkCoordinate <= 0.0  THEN
    g_fPlaneX_Site := g_fXWorkCoordinate - fLeft + 10.0;
    ELSIF g_fXWorkCoordinate > 0.0 THEN
      g_fPlaneX_Site := fRight - g_fXWorkCoordinate +10.0;
    END_IF; 
  END_IF;
(*ELSIF (dWorkCoordU >=180.0 AND dWorkCoordU <270.0)  OR (dWorkCoordU > -270.0 AND dWorkCoordU <= -180.0) THEN*)
ELSIF (dWorkCoordU >170.0 AND dWorkCoordU <190.0)  OR (dWorkCoordU > -190.0 AND dWorkCoordU <= -170.0) THEN
  fLeft := -DIV(IN1 := g_dSquareLenght,IN2 := 2.0)+10.0 + g_fCornerRadius;
  fRight := DIV(IN1 := g_dSquareLenght,IN2 := 2.0) -10.0 - g_fCornerRadius;
  IF g_fXWorkCoordinate > fLeft AND g_fXWorkCoordinate < fRight THEN
    g_bLaserOnPlane := FALSE;
  ELSE 
    g_bLaserOnPlane := TRUE;
    IF g_fXWorkCoordinate <= 0.0  THEN
    g_fPlaneX_Site := g_fXWorkCoordinate - fLeft + 10.0;
    ELSIF g_fXWorkCoordinate > 0.0 THEN
      g_fPlaneX_Site := fRight - g_fXWorkCoordinate +10.0;
    END_IF; 
  END_IF;
(*ELSIF (dWorkCoordU >=270.0 AND dWorkCoordU <360.0) OR (dWorkCoordU > -180.0 AND dWorkCoordU <= -90.0) THEN*)
ELSIF (dWorkCoordU >260.0 AND dWorkCoordU <280.0) OR (dWorkCoordU > -100.0 AND dWorkCoordU <= -80.0) THEN
    fLeft := -DIV(IN1 := g_dSquareWidth,IN2 := 2.0) + 10.0 + g_fCornerRadius;
  fRight := DIV( IN1 := g_dSquareWidth,IN2 := 2.0) -10.0 - g_fCornerRadius;
  IF g_fXWorkCoordinate > fLeft AND g_fXWorkCoordinate < fRight THEN
    g_bLaserOnPlane := FALSE;
  ELSE 
    g_bLaserOnPlane := TRUE;
    IF g_fXWorkCoordinate <= 0.0  THEN    
      g_fPlaneX_Site := g_fXWorkCoordinate - fLeft + 10.0;
    ELSIF g_fXWorkCoordinate > 0.0 THEN
      g_fPlaneX_Site := fRight - g_fXWorkCoordinate +10.0;
    END_IF; 
  END_IF;

END_IF;
